using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using WaveHarmonic.Crest;using CityForge.Environment;using CityForge.CameraSystem;
namespace CityForge.Editor {
[InitializeOnLoad] public static class CrestPondStudy {
const string Root="Assets/CityForge/Art/Environment/CrestPondStudy/";
const string Work="/Users/joelinstrum/Documents/Codex/2026-10-08/tre/work/";
static double captureAt;
static CrestPondStudy(){EditorApplication.update+=Tick;}
static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isPlaying)return;try{if(File.Exists(Work+"crest-pond")){File.Delete(Work+"crest-pond");Run();}if(captureAt>0&&EditorApplication.timeSinceStartup>captureAt){captureAt=0;Capture();}}catch(Exception e){captureAt=0;Debug.LogException(e);}}
static void Set(UnityEngine.Object target,string name,object value){var so=new SerializedObject(target);var p=so.FindProperty(name);if(p==null)throw new Exception("Missing Crest property "+name);if(value is UnityEngine.Object obj)p.objectReferenceValue=obj;else if(value is bool b)p.boolValue=b;else if(value is int i)p.intValue=i;else if(value is float f)p.floatValue=f;else if(value is Vector2 v)p.vector2Value=v;so.ApplyModifiedPropertiesWithoutUndo();}
[MenuItem("CityForge/Water Study/Crest Pond Trial")]
public static void Run(){var scene=EditorSceneManager.OpenScene("Assets/CityForge/Art/Environment/CohesiveMeadowStudy/CohesiveMeadowZoom1.unity");Directory.CreateDirectory(Root);
var old=UnityEngine.Object.FindFirstObjectByType<PondPlanarReflection>();var cam=old.sourceCamera;old.gameObject.SetActive(false);cam.tag="MainCamera";cam.GetComponent<CityForgeCameraController>().ConfigureTerrainStudy(new Vector3(133,8,130),61.955f,0);
foreach(var rig in UnityEngine.Object.FindObjectsByType<CityForgeCameraController>(FindObjectsInactive.Include,FindObjectsSortMode.None))if(rig.gameObject!=cam.gameObject)rig.enabled=false;
cam.GetUniversalAdditionalCameraData().requiresDepthTexture=true;cam.GetUniversalAdditionalCameraData().requiresColorTexture=true;
var source=AssetDatabase.LoadAssetAtPath<Material>("Packages/com.waveharmonic.crest/Runtime/Materials/Water.mat");var mat=new Material(source){name="Calm Crest pond"};
mat.SetColor("_Crest_Scattering",new Color(.035f,.12f,.13f,1));mat.SetVector("_Crest_Absorption",new Vector4(.45f,.18f,.12f,0));mat.SetFloat("_Crest_TransparencyMinimumAlpha",.04f);mat.SetFloat("_Crest_Smoothness",.94f);mat.SetFloat("_Crest_CausticsEnabled",0);mat.SetFloat("_Crest_CausticsStrength",0);mat.SetFloat("_Crest_NormalMapStrength",.012f);mat.SetFloat("_Crest_NormalMapScale",2.5f);mat.SetFloat("_Crest_NormalMapScrollSpeed",.15f);mat.SetFloat("_Crest_NormalMapTurbulenceStrength",.08f);mat.SetFloat("_Crest_FoamEnabled",0);mat.SetFloat("_Crest_PlanarReflectionsEnabled",1);mat.SetFloat("_Crest_PlanarReflectionsIntensity",.8f);mat.SetFloat("_Crest_PlanarReflectionsDistortion",.15f);
var previous=AssetDatabase.LoadAssetAtPath<Material>(Root+"CalmPond.mat");if(previous){EditorUtility.CopySerialized(mat,previous);UnityEngine.Object.DestroyImmediate(mat);mat=previous;}else AssetDatabase.CreateAsset(mat,Root+"CalmPond.mat");
var root=new GameObject("Crest calm pond system");root.SetActive(false);root.transform.position=new Vector3(133,6.8f,130);var water=root.AddComponent<WaterRenderer>();
var detail=new GameObject("Pond center of detail");detail.transform.SetParent(root.transform);detail.transform.position=new Vector3(133,16.8f,130);
Set(water,"_Camera",cam);Set(water,"_Viewpoint",detail.transform);Set(water,"_EditorMultipleViewpoints",false);Set(water,"_FollowSceneCamera",false);Set(water,"_Surface._Material",mat);Set(water,"_ScaleRange",new Vector2(4,8));Set(water,"_Slices",4);Set(water,"_Resolution",256);Set(water,"_WindSpeed",2f);Set(water,"_ClipLod._Enabled",true);Set(water,"_ClipLod._DefaultClippingState",1);Set(water,"_DefaultExcludes",(int)WaterBodyAffects.Everything);Set(water,"_Reflections._Enabled",true);Set(water,"_Reflections._Resolution",1024);Set(water,"_Reflections._Layers",~((1<<4)|(1<<2)));Set(water,"_Reflections._DisableShadows",false);Set(water,"_Reflections._FarClipPlane",650f);
var body=new GameObject("Bounded pond water");body.transform.SetParent(root.transform);body.transform.position=new Vector3(133,6.8f,130);body.transform.localScale=new Vector3(104,20,84);var bounds=body.AddComponent<WaterBody>();Set(bounds,"_Affects",(int)WaterBodyAffects.Everything);Set(bounds,"_Exclusion",(int)WaterBodyExclusion.Include);
var ground=GameObject.Find("Ground with meadow, canopy litter and dirt masks");ground.layer=30;var probeObject=new GameObject("Pond bed depth probe");probeObject.transform.SetParent(root.transform);probeObject.transform.position=new Vector3(133,6.8f,130);probeObject.transform.localScale=new Vector3(110,1,110);var probe=probeObject.AddComponent<DepthProbe>();Set(probe,"_Layers",1<<30);Set(probe,"_Resolution",512);Set(probe,"_CaptureRange",new Vector2(-10,20));
root.SetActive(true);probe.Populate();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Root+"CrestPondZoom0.unity");Debug.Log("CREST POND SETUP COMPLETE "+mat.shader.name);captureAt=EditorApplication.timeSinceStartup+12;
}
static void Capture(){var cam=GameObject.Find("Meadow presentation camera").GetComponent<Camera>();var rt=new RenderTexture(1920,1080,24);rt.Create();var prev=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var tex=new Texture2D(1920,1080,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1920,1080),0,0);tex.Apply();File.WriteAllBytes("/Users/joelinstrum/Documents/Codex/2026-10-08/tre/outputs/CrestPond_Zoom0.png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}Debug.Log("CREST POND CAPTURE COMPLETE");}
}}
